import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.testng.annotations.Test;

public class BeamLengthTest {
    @Test
    public void testCreateBeamLength() {
        WebDriver driver = new ChromeDriver();
        driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/master-data/beam-length");

        driver.findElement(By.xpath("//button[contains(text(),'Add Record')]")).click();
        driver.findElement(By.id("denier")).sendKeys("234");
        driver.findElement(By.id("reed")).sendKeys("23");
        driver.findElement(By.id("beamSize")).sendKeys("2323");
        driver.findElement(By.id("beamMeter")).sendKeys("34");
        driver.findElement(By.id("beamDish")).sendKeys("34");
        driver.findElement(By.xpath("//button[contains(text(),'Submit')]")).click();
    }
}
